CREATE TABLE cabinets (
    id UUID PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE
);

ALTER TABLE app_users ADD COLUMN cabinet_id UUID REFERENCES cabinets(id);

INSERT INTO cabinets (id, name) VALUES
