    WHEN id IN ('11111111-1111-1111-1111-111111111111', '55555555-5555-5555-5555-555555555501', '55555555-5555-5555-5555-555555555502', '55555555-5555-5555-5555-555555555503') THEN '77777777-7777-7777-7777-777777777701'::uuid
